import math

def get_prime_factors(x):
    """Get prime factors of x"""
    factors = {}
    d = 2
    while d * d <= x:
        while x % d == 0:
            factors[d] = factors.get(d, 0) + 1
            x //= d
        d += 1
    if x > 1:
        factors[x] = factors.get(x, 0) + 1
    return list(factors.keys())

def get_divisors(n):
    """Get all divisors of n greater than 1"""
    divs = [1]
    i = 1
    while i * i <= n:
        if n % i == 0:
            divs.append(i)
            if i * i != n:
                divs.append(n // i)
        i += 1
    return [d for d in divs if d > 1]

def gcd(a, b):
    """Compute GCD using math.gcd or Euclidean algorithm"""
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    """Compute LCM"""
    if a == 0 or b == 0:
        return 0
    return abs(a * b) // math.gcd(a, b)

def gcd_m(a, b):
    while b:
        a, b = b, a % b
    return a

def find_coprime_pairs(arr):
    """Find pairs that are coprime, return them in order"""
    pairs = []
    for i in range(len(arr)):
        for j in range(i + 1, min(i + 2, len(arr))):
            if i + 1 < len(arr) and j == len(arr) - 1:
                if i == len(arr) - 2 and j == len(arr) - 1:
                    # wrap around
                    if gcd_m(arr[i], arr[j]) == 1:
                        pairs.append((arr[i], arr[j]))
    return pairs

