    # Store prime counts for each position
    prime_counts = [get_prime_counts(x) for x in a]
    all_primes = set()
    for fc in prime_counts:
        all_primes.update(fc.keys())

    # Bipartite graph: positions 0, 2, 4, ... vs 1, 3, 5, ...
    # Since i + j is odd, one index is even (0-based: odd index) and one is odd (0-based: even index)

    left = []   # positions with odd 1-based index (even 0-based) -> 0, 2, 4, ...
    right = []  # positions with even 1-based index (odd 0-based) -> 1, 3, 5, ...

    for i in range(n):
        if i % 2 == 0:
            left.append(i)
        else:
            right.append(i)

    # For each prime, compute max flow between left and right positions connected by good pairs
    # Each connection can transfer at most min(count in left, count in right) times for that prime

    total_operations = 0
    for p in all_primes:
        cnt_left = [prime_counts[i].get(p, 0) for i in range(n) if i % 2 == 0]
        cnt_right = [prime_counts[i].get(p, 0) for i in range(n) if i % 2 == 1]

        # Build edges for this prime
        edges = []
        for i in range(len(left)):
            if cnt_left[i] == 0:
                continue
            for j in range(len(right)):
                if cnt_right[j] == 0:
                    continue
                # Check if there's a good pair between left[i] and right[j]
                li, lj = left[i], right[j]
                if (li, lj) in good_pairs or (lj, li) in good_pairs:
                    edges.append((i, j))

        # For each prime, we can perform operations:
        # Each operation uses an edge and consumes 1 from both endpoints
        # This equates to finding maximum bipartite matching weighted by counts
        # But since we can use each edge multiple times, total = sum over all edges of counts available

        # Actually, since each good pair is independent, we need to solve max flow
        # But simpler: total = sum over all good edges of min(cnt_left, cnt_right)
        # Wait, no - one good pair contributes multiple times if both have multiple copies

        # The key insight: each good pair (u, v) with shared prime p contributes 
        # min(count_p(a[u]), count_p(a[v])) to total operations

        for (u, v) in good_pairs:
            count_u = prime_counts[u].get(p, 0)
            count_v = prime_counts[v].get(p, 0)
            if count_u > 0 and count_v > 0:
                total_operations += min(count_u, count_v)

    return str(total_operations) + '\n'


