import sys

def solution(input_str):
    lines = input_str.strip().split('\n')
    if len(lines) == 0:
        return ''

    parts = lines[0].split()
    n, m = int(parts[0]), int(parts[1])

    edges = []
    for i in range(1, m + 1):
        if i >= len(lines):
            break
        parts = lines[i].split()
        u, v, w = int(parts[0]), int(parts[1]), int(parts[2])
        edges.append((u, v, w))

    if m == n - 1:
        return ''

    # Sort edges by weight for Kruskal's algorithm
    edges_by_weight = sorted(edges, key=lambda x: x[2])

    parent = list(range(n + 1))

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        px, py = find(x), find(y)
        if px != py:
            parent[px] = py
            return True
        return False

    # Track MST edges and build adjacency
    mst_edges = set()
    adj = [[] for _ in range(n + 1)]

    for u, v, w in edges_by_weight:
        if union(u, v):
            mst_edges.add(tuple(sorted((u, v))))
            adj[u].append((v, w))
            adj[v].append((u, w))

    # BFS to compute depths and parents (for root start at 1)
    LOG = 20
    up = [[0] * (n + 1) for _ in range(LOG)]
    weight_up = [[0] * (n + 1) for _ in range(LOG)]
    depth = [0] * (n + 1)

    queue = [1]
    visited = [False] * (n + 1)
    visited[1] = True
    depth[1] = 0
    parent_1 = [0] * (n + 1)

    while queue:
        u = queue.pop(0)
        for v, w in adj[u]:
            if not visited[v]:
                visited[v] = True
                depth[v] = depth[u] + 1
                parent_1[v] = u
                queue.append(v)

    # Initialize level 0 of binary lifting
    for v in range(1, n + 1):
        up[0][v] = parent_1[v] if parent_1[v] else 0

    # Find edge weights to parent for each vertex
    edge_to_parent_weight = [0] * (n + 1)
    for u, v, w in edges:
        if tuple(sorted((u, v))) in mst_edges:
            if parent_1[u] == v:
                edge_to_parent_weight[u] = w
            elif parent_1[v] == u:
                edge_to_parent_weight[v] = w

    for v in range(1, n + 1):
        weight_up[0][v] = edge_to_parent_weight[v]

    # Build binary lifting table
    for j in range(1, LOG):
        for v in range(1, n + 1):
            up_j_prev = up[j-1][v]
            if up_j_prev != 0:
                up[j][v] = up[j-1][up_j_prev]
                weight_up[j][v] = max(weight_up[j-1][v], weight_up[j-1][up_j_prev])
            else:
                up[j][v] = 0
                weight_up[j][v] = weight_up[j-1][v]

    def query_max_on_path(u, v):
        if depth[u] < depth[v]:
            u, v = v, u

        result = 0
        diff = depth[u] - depth[v]

        for j in range(LOG):
            if (diff >> j) & 1:
                result = max(result, weight_up[j][u])
                u = up[j][u]

        if u == v:
            return result

        for j in range(LOG - 1, -1, -1):
            if up[j][u] != up[j][v]:
                result = max(result, weight_up[j][u])
                result = max(result, weight_up[j][v])
                u = up[j][u]
                v = up[j][v]

        result = max(result, weight_up[0][u])
        result = max(result, weight_up[0][v])

        return result

    # Collect outputs only for non-MST edges
    output_order = []
    for i, orig_edge in enumerate(edges):
        u, v, w = orig_edge
        key = tuple(sorted((u, v)))
        if key not in mst_edges:
            output_order.append(i)

    result_lines = []
    for idx in output_order:
        u, v, w = edges[idx]
        res = query_max_on_path(u, v)
        result_lines.append(str(res))

    return '\n'.join(result_lines)


