def solution(input_data):
    lines = input_data.strip().split('\n')
    n = int(lines[0])
    points = []
    for i in range(1, n + 1):
        parts = lines[i].split()
        points.append((int(parts[0]), int(parts[1])))

    def cross_product(o, a, b):
        """Cross product to determine orientation of point b relative to line o->a"""
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    def nCr(n, r):
        """Calculate n choose r"""
        if r < 0 or r > n:
            return 0
        if r == 0 or r == n:
            return 1
        if r > n // 2:
            r = n - r

        result = 1
        for i in range(r):
            result = result * (n - i) // (i + 1)
        return result

    result = 0
    for i in range(n):
        for j in range(i + 1, n):
            # Count points strictly on each side of line through points[i] and points[j]
            left = 0
            right = 0

            for k in range(n):
                if k == i or k == j:
                    continue

                cp = cross_product(points[i], points[j], points[k])

                if cp > 0:
                    left += 1
                elif cp < 0:
                    right += 1

            # If both sides have at least 3 points, we can form triangles
            if left >= 3 and right >= 3:
                result += nCr(left, 3) * nCr(right, 3)

    # Divide by 2 because each separating line is processed twice (once for each direction)
    return result // 2

