def solution(input_str):
    lines = input_str.strip().split('\n')
    n, k = map(int, lines[0].split())
    s = lines[1]

    # If k > n, it's impossible
    if k > n:
        return "NO"

    # states = {(run_len, has_k, forced_violation)}
    # run_len: current consecutive N's count
    # has_k: whether we've achieved exactly k consecutive N's in a valid run
    # forced_violation: whether we're forced to have a run > k (invalid)
    states = {(0, False, False)}

    for i in range(n):
        new_states = set()
        for run_len, has_k, forced in states:
            char = s[i]

            if char == 'Y':
                # Y ends current N-run, reset to 0
                new_states.add((0, has_k, forced))
            elif char == 'N':
                # Must be 'N', increment run length
                new_run = run_len + 1
                if new_run > k and not forced:
                    # Forced violation - run exceeds k
                    new_states.add((new_run, has_k, True))
                elif new_run >= k:
                    # Run equals k, mark target achieved
                    new_states.add((new_run, True, False))
                else:
                    new_states.add((new_run, has_k, False))
            elif char == '?':
                # Can choose 'Y' or 'N'
                # Option 1: treat as 'Y', ends run
                new_states.add((0, has_k, forced))

                # Option 2: treat as 'N', increment run
                new_run = run_len + 1
                if new_run > k and not forced:
                    new_states.add((new_run, has_k, True))
                elif new_run >= k:
                    new_states.add((new_run, True, False))
                else:
                    new_states.add((new_run, has_k, False))

        states = new_states

    # Check if there's any valid state with has_k=True and not forced
    result = any(has_k and not forced for run_len, has_k, forced in states)
    return "YES" if result else "NO"

