                while True:
                    if current in final_visited:
                        # Hit a node processed in previous search, no new cycle
                        break

                    if current in path:
                        # Cycle detected in current path
                        cycle_idx = path.index(current)
                        for i in range(cycle_idx, len(path)):
                            cycle_set.add(path[i])
                        break

