def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])

    # Parse the adjacency matrix
    # adj[i][j] = cost for city i to build rail to city j
    adj = [[0] * n for _ in range(n)]
    for i in range(n):
        row = list(map(int, lines[1 + i].split()))
        idx = 0
        for j in range(n):
            if j != i:
                adj[i][j] = row[idx]
                idx += 1

    # Precompute rank preferences: lower rank = better preference
    # rank[i][j] = rank of city j in city i's preferences
    rank = [[0] * n for _ in range(n)]
    for i in range(n):
        # Sort all cities by cost (lower cost = better = lower rank value)
        items = [(adj[i][j], j) for j in range(n) if j != i]
        items.sort()
        for r, (cost, city) in enumerate(items, 1):  # Start from 1
            rank[i][city] = r

    # Check if a matching is stable
    def is_stable(matching):
        """Return True if matching is stable, False otherwise"""
        for i in range(n):
            if matching[i] == -1:
                return False
            for j in range(i + 1, n):
                # Check if i and j are NOT paired with each other
                if matching[i] != j and matching[j] != i:
                    # Check if both prefer each other over their current partners
                    # rank[i][j] < rank[i][matching[i]] means i prefers j
                    # rank[j][i] < rank[j][matching[j]] means j prefers i
                    if rank[i][j] < rank[i][matching[i]] and rank[j][i] < rank[j][matching[j]]:
                        return False
        return True

    def find_blocking_pair(matching):
        """Find a blocking pair (i, j) if one exists"""
        for i in range(n):
            for j in range(i + 1, n):
                if matching[i] != j and matching[j] != i:
                    if rank[i][j] < rank[i][matching[i]] and rank[j][i] < rank[j][matching[j]]:
                        return (i, j)
        return None

    # Try multiple initial matchings to find a stable one
    best_matching = None

    def make_random_matching():
        """Create a random perfect matching"""
        matching = list(range(n))
        random.shuffle(matching)
        result = [-1] * n
        for i in range(0, n, 2):
            if i + 1 < n:
                u, v = matching[i], matching[i + 1]
                result[u] = v
                result[v] = u
        return result

    # Try 200 random initial matchings
    for _ in range(200):
        matching = make_random_matching()

        # Try to improve by resolving blocking pairs
        for _ in range(100):
            blocking = find_blocking_pair(matching)
            if blocking is None:
                break
            i, j = blocking
            matching[i] = j
            matching[j] = i

        if is_stable(matching):
            best_matching = matching
            break

    if best_matching is None:
        # Also try deterministic approaches
        # Always pair i with (i+1) % n (bi-partition into pairs)
        matching = [-1] * n
        for i in range(0, n, 2):
            if i + 1 < n:
                u, v = i, i + 1
                matching[u] = v
                matching[v] = u

        # Try swapping adjacent pairs
        improved = False
        for _ in range(50):
            swapped = False
            for i in range(0, n - 1, 2):
                for j in range(i + 1, n - 1, 2):
                    if j + 1 < n:
                        orig_matchings = list(matching)
                        u1, v1 = i, i + 1
                        u2, v2 = j, j + 1

                        # Try creating new pairings (i,j) and (k,l) where original were (i,k) and (j,l)
                        if matching[u1] == v2 and matching[u2] == v1:
                            matching[u1] = v2
                            matching[u2] = v1
                            if is_stable(matching):
                                break
                            else:
                                matching = orig_matchings.xlsx

            if not swapped and is_stable(matching):
                break

    if best_matching is None:
        # Final fallback: try greedy closest pairing
        matching = [-1] * n
        used = [False] * n
        for i in range(n):
            if not used[i]:
                for j in range(n):
                    if j != i and not used[j]:
                        matching[i] = j
                        matching[j] = i
                        used[i] = True
                        used[j] = True
                        break

        # Check if stable
        if not is_stable(matching):
            # Keep trying random approaches
            for _ in range(500):
                for _ in range(200):
                    result = [find_blocking_pair(matching)]
                    if result[0][1] == i or result[0][0] == matching[i]:
                        continue
                    blocking = result[0]
                    i, j = blocking
                    matching[i] = j
                    matching[j] = i
                if is_stable(matching):
                    break
        else:
            pass

    if best_matching is None:
        # Try one more deterministic approach
        matching = [-1] * n
        for i in range(0, n, 2):
            matching[i] = i + 1 if i + 1 < n else 0
            matching[i + 1] = i if i + 1 < n else i
        best_matching = matching

    # Verify and output
    output = []
    if best_matching:
        stable_check = is_stable(best_matching)
        if stable_check:
            for i in range(n):
                output.append(str(best_matching[i] + 1))
        else:
            output.append("-1")
            # Try more extensive search
            for _ in range(1000):
                matching = make_random_matching()
                for _ in range(2000):
                    blocking = find_blocking_pair(matching)
                    if blocking is None:
                        break
                    i, j = blocking
                    matching[i] = j
                    matching[j] = i
                if is_stable(matching):
                    for i in range(n):
                        output.append(str(matching[i] + 1))
                    best_check = True
                    break
            if not best_check and len(output) == 1:
                output = ["-1"]

    return '\n'.join(output) + '\n'

