def is_gp(seq):
    """Check if a sequence is a geometric progression"""
    n = len(seq)
    if n <= 1:
        return True
    if all(x == 0 for x in seq):
        return True

    if seq[0] == 0:
        return False

    for i in range(2, n):
        # Using cross-multiplication to avoid division and floating point issues
        if seq[i] * seq[i-2] != seq[i-1] * seq[i-1]:
            return False
    return True


def solution(input_str):
    """
    Determine if sequence is GP, can be made GP by removing 1 element, or neither
    Returns '0', '1', or '2'
    """
    tokens = input_str.strip().split()

    if len(tokens) < 2:
        return '2\n'

    n = int(tokens[0])
    seq = [int(x) for x in tokens[1:n+1]]

    # Check if already a GP
    if is_gp(seq):
        return '0\n'

    # Try removing one element
    for i in range(len(seq)):
        new_seq = seq[:i] + seq[i+1:]
        if is_gp(new_seq):
            return '1\n'

    return '2\n'


