                adj[u].append(v)
                adj[v].append(u)

    # Helper to compute component of inactive nodes
    def get_inactive_component_size(active_nodes, start_node):
        if start_node in active_nodes:
            return 0
        inactive = set(range(N)) - active_nodes
        # BFS within inactive nodes
        visited = set()
        queue = deque([start_node])
        visited.add(start_node)
        while queue:
            curr = queue.popleft()
            for neighbor in adj[curr]:
                if neighbor in inactive and neighbor not in visited:
                    visited.add(neighbor)
                    queue.append(neighbor)
        return len(visited)

    def compute_potential_sum(order):
        """
        Given an activation order, compute total potential sum.
        The first node in order is kickstarted manually.
        """
        active_nodes = set()
        total = 0

        # Kickstart first node
        first = order[0]
        total += get_inactive_component_size(active_nodes, first)
        active_nodes.add(first)

        # Then activate others in order
        for node in order[1:]:
            incomp = get_inactive_component_size(active_nodes, node)
            total += incomp
            active_nodes.add(node)

        return total

    # Find all valid topological orders using BFS
    # Try multiple strategies to maximize potential sum

    # Strategy 1: Try each node as breakpoint
    best = 0
    for kickstart in range(N):
        # BFS from kickstart to get a valid order
        active = {kickstart}
        order = [kickstart]
        queue = deque([kickstart])
        while queue:
            node = queue.popleft()
            for neighbor in adj[node]:
                if neighbor not in active:
                    active.add(neighbor)
                    order.append(neighbor)
                    queue.append(neighbor)

        # With this walk on graph, compute potential
        total = 0
        active = set()

        # Kickstart
        first = order[0]
        # Potential of kickstart = size of all currently inactive + itself reachable
        neighbors_of_inactive = []
        incomp = set(range(N))
        visited = {first}
        q = deque([first])
        while q:
            u = q.popleft()
            for v in adj[u]:
                if v in incomp:
                    visited.add(v)
                    q.append(v)
                    incomp.discard(v)
        total += len(visited)
        active.add(first)

        # Now activate rest of nodes in order
        for node in order[1:]:
            if node not in {v for v, v_in_active := ([''] * N) for v in range(N) if not v_in_active}
            # Node needs at least one neighbor active to power up
            can_power = any(n in active for n in adj[node]) if adj[node] else False
            if can_power:
                # Compute potential (inactive component from this node)
                current_inactive = set(range(N)) - active
                visited2 = {node}
                q2 = deque([node])
                while q2:
                    u = q2.popleft()
                    for v in adj[u]:
                        if v in current_inactive and v not in visited2:
                            visited2.add(v)
                            q2.append(v)
                total += len(visited2)
                active.add(node)

    # Strategy 2: Greedy approach - maximize potential at each step
    best = 0
    for kickstart in range(N):
        active = {kickstart}
        total = len(set(range(N)))  # kickstart's potential

        while len(active) < N:
            # Find inactive nodes that can be powered
            candidates = []
            for node in range(N):
                if node not in active:
                    # Check if any neighbor is active
                    can_power = any(n in active for n in adj[node]) if adj[node] else False
                    if can_power:
                        candidates.append(node)

            if not candidates:
                break

            # Greedily pick node with max potential
            max_pot = -1
            best_node = candidates[0]
            for node in candidates:
                current_inactive = set(range(N)) - active
                visited = {node}
                q = deque([node])
                while q:
                    u = q.popleft()
                    for v in adj[u]:
                        if v in current_inactive and v not in visited:
                            visited.add(v)
                            q.append(v)
                pot = len(visited)
                if pot > max_pot:
                    max_pot = pot
                    best_node = node

            # Activate best candidate
            total += max_pot
            active.add(best_node)

        best = max(best, total)

    # Strategy 3: Consider line graph pattern for connected components
    # Try all possible BFS tree orders
    if N > 0:
        # Find actual maximum
        candidates = set()
        for start in range(N):
            active = {start}
            total = N
            while len(active) < N:
                can_power = []
                for node in range(N):
                    if node not in active:
                        if any(n in active for n in adj[node]) and adj[node]:
