# Parse a number, supports "l-r" format for concatenating range
def parse_number(i, n):
    """Parse a number starting at position i, return (val, len_str, chars_consumed)"""
    if i >= len(n):
        return 0, 0, 0

    # Skip if leading digit
    start = i
    while i < len(n) and n[i].isdigit():
        i += 1

    if start == i:
        return 0, 0, 0

    number_str = n[start:i]

    # Check for minus sign indicating range l-r
    if i + 1 < len(n) and n[i + 1] == '-':
        # Skip the '-'
        i += 1
        if i + 1 < len(n) and n[i + 1].isdigit():
            i += 1

    return int(number_str), (i - start), (i - start)


