class Parser:
    def __init__(self, text):
        self.text = text
        self.pos = 0
        self.len = len(text.strip())

    def is_white(self, text, pos):
        return pos < len(text) and text[pos].isspace()

    def skip_white(self):
        while self.pos < self.len and self.is_white(self.text, self.pos):
            self.pos += 1

    def peek_char(self):
        if self.pos < self.len and not self.is_white(self.text, self.pos):
            return self.text[self.pos]
        return None

    def consume_char(self, expected=None):
        self.skip_white()
        if self.pos < self.len:
            if expected is not None and self.text[self.pos] != expected:
                raise ValueError(f"Expected '{expected}' at pos {self.pos}, got '{self.text[self.pos]}'")
            ch = self.text[self.pos]
            self.pos += 1
            return ch
        return None

    def parse_number(self):
        """Parse a number which can be 'l-r' format"""
        start = self.pos
        self.skip_white()

        # Collect digits for l
        while self.pos < self.len and self.text[self.pos].isdigit():
            self.pos += 1

        l = int(self.text[start:self.pos])

        # Check for '-' and more digits
        if self.peek_char() == '-':
            self.consume_char('-')
            r_start = self.pos
            while self.pos < self.len and self.text[self.pos].isdigit():
                self.pos += 1
            r = int(self.text[r_start:self.pos])
            return l, r

        return l, l

    def parse_term(self):
        """Parse a single term"""
        l, r = self.parse_number()

        ch = self.peek_char()
        if ch == '(' and len(self.text) > self.pos:
            # term = number(expr) - repeat expr l times
            self.consume_char('(')
            expr_result, expr_len = self.parse_expr()
            self.consume_char(')')
            return self.replicate(expr_result, expr_len, l)
        elif ch == '-' or len(self.text) > self.pos:
            # term could be l-r, return the two numbers separately
            return l, r
        else:
            return l, r

    def replicate(self, expr_val, expr_len, count):
        """Concatenate expr_val, count times"""
        MOD = 10**9 + 7
        if count == 0:
            return 0, 0

        # Concatenate expr_val, count times
        result = 0
        for _ in range(count):
            result = concat_numbers_sequence_result(result, expr_val, expr_len, len(str(result)))
        return result % MOD, expr_len * count

    def concat_numbers_sequence_result(self, current, new_val, new_len, current_len):
        """Concatenate current with new_val given new_len digits"""
        MOD = 10**9 + 7
        return (current * pow(10, new_len, MOD) + new_val) % MOD

    def parse_expr(self):
        """Parse an expression: term | expr '+' term"""
        term1_l, term1_r = self.parse_term()

        # Parse range concatenation l-r
        if term1_l < term1_r:
            concat_vals = []
            for i in range(term1_l, term1_r + 1):
                str_i = str(i)
                concat_vals.append((i, len(str_i)))
            concat_result = self.concatenate_range(concat_vals)
            return concat_result

        ch = self.peek_char()
        while ch == '+' and self.pos < self.len:
            self.consume_char('+')
            term2_l, term2_r = self.parse_term()

            # Parse range concatenation
            if term2_l < term2_r:
                concat_vals = []
                for i in range(term2_l, term2_r + 1):
                    str_i = str(i)
                    concat_vals.append((i, len(str_i)))
                concat_result = self.concatenate_range(concat_vals)

                # Handle addition with the previous terms
                current_val, current_len = term1_l, digit_len(term1_l)
                current_val, current_len = concat_numbers_sequence_result(current_val, term1_r - term1_l, digit_len(term1_r - term1_l), current_len)
                current_val, current_len = concat_numbers_sequence_result(current_val, term2_l, digit_len(term2_l), current_len)
                current_val, current_len = concat_numbers_sequence_result(current_val, term2_r - term2_l, digit_len(term2_r - term2_l), current_len)

                return current_val, current_len
            else:
                # Single number
                self.consume_char(')')
                return term2_l, digit_len(term2_l)

        return term1_l, digit_len(term1_l)

    def parse_term2(self):
        """Parse a term including l-r addition"""
        l, r = self.parse_number()
        ch = self.peek_char()

        if ch == '(' and self.pos < self.len and self.text[self.pos] == '(':
            self.consume_char('(')
            expr_val, expr_len = self.parse_expr()
            self.consume_char(')')
            return self.replicate(expr_val, expr_len, l)

        return l, r


def digit_len(n):
    """Get digit length of number n"""
    return len(str(n))


def parse_expression(s):
