class Parser:
    def __init__(self, text):
        self.text = text
        self.pos = 0
        self.len = len(text)

    def is_white(self):
        while self.pos < self.len and self.text[self.pos].isspace():
            self.pos += 1
        return self.pos < self.len and self.text[self.pos].isspace()

    def peek(self):
        if self.pos < self.len and not self.is_white():
            return self.text[self.pos]
        return None

    def consume(self, expected=None):
        self.skip_white()
        if expected is not None and self.text[self.pos] != expected:
            return None
        ch = self.text[self.pos]
        self.pos += 1
        return ch

    def skip_white(self):
        while self.pos < self.len and self.text[self.pos].isspace():
            self.pos += 1

    def parse_expression(self):
        """Parse full expression"""
        return self.parse_expr()

    def parse_expr(self):
        """<expression> ::= <term> | <expression> '+' <term>"""
        result, total_len = self.parse_term()

        while self.peek() == '+':
            self.consume('+')
            term2, length = self.parse_term()
            # Simplified concatenation
            result_str = str(result) + str(term2)
            result, total_len = int(result_str), len(result_str)

        return result, total_len

    def parse_term(self):
        """<term> ::= <number> | <number> '-' <number> | <number> '(' <expression> ')'"""
        l, r = self.parse_number()
        if not self.pos < self.len: return l, r

        ch = self.peek()
        if ch == '(':
            l, r = self.parse_number()
            self.consume('(')
            term, length = self.parse_expr()
            self.consume(')')

            # Repeat term l times
            result_str = term * l
            return int(result_str), len(result_str)

        # Concatenate from l to r
        if l < r:
            result_str = ""
            for i in range(l, r + 1):
                result_str += str(i)
            return int(result_str), len(result_str)

        return l, r

    def parse_number(self):
        """<number> ::= <pos_digit> | <number> <digit>"""
        if self.pos >= self.len: return 0, 0

        num_str = ""
        while self.pos < self.len and self.text[self.pos].isdigit():
            num_str += self.text[self.pos]
            self.pos += 1

        result = int(num_str) if num_str else 0

        return result, len(num_str)


def val_concatenate(a, b_str):
    """Concatenate a with string b_str, return int and length"""
    if not a:
        return int(b_str), len(b_str)
    result_str = str(a) + b_str
