    for i in range(1, vlen):
        j = pi[i-1]
        while j > 0 and virus[i] != virus[j]:
            j = pi[j-1]
        if virus[i] == virus[j]:
            j += 1
        pi[i] = j

    # Build KMP automaton: next_state[k][c] gives the next k after matching char c
    nxt = [[0] * 26 for _ in range(vlen + 1)]
    for k in range(vlen + 1):
        for c in range(26):
            ch = chr(ord('A') + c)
            t = k
            while t > 0 and (virus[t] if t < vlen else '') != ch:
                t = pi[t-1]
            if t < vlen and virus[t] == ch:
                nxt[k][ord(ch) - ord('A')] = t + 1
            else:
                nxt[k][ord(ch) - ord('A')] = t

    # dp[i][j][k] = max LCS length using s1[:i] and s2[:j] with virus prefix k
    dp = [[[0] * (vlen + 1) for _ in range(m + 1)] for _ in range(n + 1)]
    parent = [[[None] * (vlen + 1) for _ in range(m + 1)] for _ in range(n + 1)]

    # Base case: empty prefixes have length 0
    for k in range(vlen + 1):
        dp[0][0][k] = 0

    for i in range(n + 1):
        for j in range(m + 1):
            if i == 0 and j == 0:
                continue
            for k in range(vlen + 1):
                # Option 1: Skip s1[i-1]
                if i > 0 and dp[i-1][j][k] > dp[i][j][k]:
                    dp[i][j][k] = dp[i-1][j][k]
                    parent[i][j][k] = (i-1, j, k, 'SKIP_S1')

                # Option 2: Skip s2[j-1]
                if j > 0 and dp[i][j-1][k] > dp[i][j][k]:
                    dp[i][j][k] = dp[i][j-1][k]
                    parent[i][j][k] = (i, j-1, k, 'SKIP_S2')

            if i > 0 and j > 0 and s1[i-1] == s2[j-1]:
                for k_src in range(vlen + 1):
                    if dp[i-1][j-1][k_src] < 0:
                        continue
                    nk = nxt[k_src][ord(s1[i-1]) - ord('A')]
                    if nk < vlen:  # Virus not completed
                        cand = dp[i-1][j-1][k_src] + 1
                        if cand > dp[i][j][nk]:
                            dp[i][j][nk] = cand
                            parent[i][j][nk] = (i-1, j-1, k_src, 'MATCH')

