    """Compute factorial with modulo."""
    result = 1
    for i in range(1, n + 1):
        result = (result * i) % mod
    return result

def inverse(n, mod):
    """Compute modular inverse using Fermat's little theorem."""
    return pow(n, mod - 2, mod)

