    for c in cnt:
        max_factors = max(max_factors, c)

    fact = [1] * (max_factors + 1)
    for i in range(2, max_factors + 1):
        fact[i] = (fact[i - 1] * i) % MOD

    inv_fact = [1] * (max_factors + 1)
    inv_fact[max_factors] = inverse(fact[max_factors], MOD)
    for i in range(max_factors - 1, -1, -1):
        inv_fact[i] = (inv_fact[i + 1] * (i + 1)) % MOD

    def nCr_mod(n, r):
        """Compute C(n, r) modulo MOD."""
