            continue

        # Record first and last position for each unique value
        first = {}
        last = {}
        for i, x in enumerate(a):
            if x not in first:
                first[x] = i
                last[x] = i
            else:
                last[x] = i

        # Get unique values in sorted order
        sorted_unique = sorted(first.keys())
        m = len(sorted_unique)

        if m == 0:
            results.append("0")
            continue

        # Find longest chain where last[prev] < first[curr]
        # Use patience sort / binary search for O(m log m)
        tails = []  # tails[k] = minimum last value for chain of length k+1

        for v in sorted_unique:
            f, l = first[v], last[v]

            # Binary search: find rightmost tails[pos] < f
            lo, hi = 0, len(tails)
            while lo < hi:
                mid = (lo + hi) // 2
                if tails[mid] < f:
                    lo = mid + 1
                else:
                    hi = mid

            if lo == len(tails):
                tails.append(l)
            else:
                tails[lo] = l

        max_kept = len(tails)
        results.append(str(m - max_kept))

    return '\n'.join(results)


