            cache[(r, c)] = ans
            return ans
        else:
            count = count_ways(r, c + 1, cache)
            cache[(r, c)] = count
            return count

    if not check_initial_valid():
        return '0'

    cache = {}
    result = count_ways(0, 0, cache)
    return str(result)

