def solve(p, n):
    """
    Greedy approach:
    - Process lanterns from left to right
    - For each lantern, try to ensure it gets illuminated from the left
    - If already illuminated from left, we can mark its direction based on coverage to the right
    - If not illuminated from left, try to illuminate THIS lantern from the right

    Key insight: For each lantern i, we need at least one lantern j != i to illuminate it.
    - A lantern j < i can illuminate i if ans[j] == 'R' and j + p[j] >= i
    - A lantern j > i can illuminate i if ans[j] == 'L' and j - p[j] <= i

    Strategy: When we reach lantern i, we maintain which lanterns have been set (point L or R).
    If lantern i is not illuminated from the left, we need to either:
    1. Find a right neighbor that can illuminate it (set to L)
    2. Allow it to be unlit temporarily and fix later

    We process left to right and try to fix any unilluminated lanterns.
    """
    ans = [''] * n
    # Track which lanterns are confirmed to be illuminated from left
    # after processing positions 0..i

    # Process each lantern
    for i in range(n):
        # Check if lantern i is illuminated from left by any previous lantern
        illuminated = False

        # A left neighbor j illuminates i if ans[j] == 'R' and j + p[j] >= i
        for j in range(i-1, max(-1, i - max(p[i-1:i-1], [0]) - 200, -1) - 1, -1):
            if j >= 0 and ans[j] == 'R' and j + p[j] >= i:
                illuminated = True
                break

        if not illuminated:
            # Lantern i is not illuminated from left yet
            # Try to get it illuminated from right
            # Look for a right neighbor j that can illuminate i (pointing left)
            # i.e., ans[j] == 'L' and j - p[j] <= i

            # Try right neighbors
            for j in range(i+1, n):
                if ans[j] == 'L' and j - p[j] <= i:
                    illuminated = True
                    break

            if not illuminated:
                # Lantern i is currently unilluminated
                # Set direction to right (it will help illuminate to the right)
                ans[i] = 'R'
            else:
                # i is illuminated
                # Set direction based on what we need
                # If it was illuminated from left, point left
                # Otherwise (from right), point right
                # But we need to be careful - we're setting ans[i] now
                # Check what effectively illuminated it
                for j in range(i-1, -1, -1):
                    if ans[j] == 'R' and j + p[j] >= i:
                        ans[i] = 'L'
                        break
                else:
                    ans[i] = 'R'
        else:
            # i is illuminated from left
            # Determine its direction
            # If left neighbor is pointing R and reaching i, we can try pointing L
            # Otherwise point R

            # Try to find which left lantern is illuminating i
            for j in range(i-1, -1, -1):
                if ans[j] == 'R' and j + p[j] >= i:
                    ans[i] = 'L'
                    break
            else:
                ans[i] = 'R'

    # Check if all lanterns are actually illuminated
    final_illuminated = [False] * n

    for i in range(n):
        for j in range(n):
            if i == j:
                continue
            # Check if j illuminates i
            if ans[j] == 'L':
                # j illuminates [j-p[j], j-1]
                if i >= j - p[j] and i != j:
                    final_illuminated[i] = True
                    break
                if i == j:
                    if i >= j - p[j]:
                        pass  # i is j itself, already checked
            else:  # ans[j] == 'R'
                # j illuminates [j+1, j+p[j]]
                if i >= j + 1 and i <= j + p[j]:
                    final_illuminated[i] = True
                    break

    if all(final_illuminated):
        return ans
    else:
        # Try a different approach: set each lantern to point right
        # and see if we can cover everyone
        ans = ['R'] * n
        final_illuminated = [False] * n

        for i in range(n):
            for j in range(n):
                if i == j:
                    continue
                if ans[j] == 'L':
                    if i >= j - p[j] and i != j:
                        final_illuminated[i] = True
                        break
                else:  # 'R'
                    if i >= j + 1 and i <= j + p[j]:
                        final_illuminated[i] = True
                        break

        return ans if all(final_illuminated) else None



