def greedy_solve(p, n):
    ans = [''] * n
    covered = [False] * n

    # Process left to right
    # For each lantern, ensure it gets covered
    for i in range(n):
        if not covered[i]:
            # Try to get covered from left
            can_from_left = False
            for j in range(i-1, -1, -1):
                if ans[j] == 'R' and j + p[j] >= i:
                    can_from_left = True
                    break

            if can_from_left:
                covered[i] = True
            else:
                # Need to get from right
                # Set rightmost available to L that can cover us
                found = False
                for j in range(i+1, n):
                    if ans[j] == '':
                        if j - p[j] <= i:
                            ans[j] = 'L'
                            found = True
                            break

                if found:
                    covered[i] = True
                else:
                    # All right neighbors are set or can't reach
                    # Set this lantern to R to help future lanterns
                    ans[i] = 'R'
                    covered[i] = False  # Not currently covered, hope future covers it

    # Final check - if not all covered, try alternate approach
    if not all(covered):
        # Try all pointing right
        ans = ['R'] * n

        # Mark all illuminated
        final_cov = [False] * n
        for i in range(n):
            for j in range(n):
                if i == j:
                    continue
                if ans[j] == 'R':
                    if j + 1 <= i <= j + p[j]:
                        final_cov[i] = True
                        break
            if final_cov[i]:
                break

        if not all(final_cov):
            # Try all pointing left
            ans = ['L'] * n
            final_cov = [False] * n
            for i in range(n):
                for j in range(n):
                    if i == j:
                        continue
                    if ans[j] == 'L':
                        if j - p[j] <= i < j:
                            final_cov[i] = True
                            break
                if final_cov[i]:
                    break

        if not all(final_cov):
            return None
        else:
            return ans

    return ans


